      //     slide in and out of alignment instead of being locked together.
      dAmp: between(r, 0.15, 0.45),  dW: between(r, 0.04, 0.09),  dP: between(r, 0, 6.283),
      // (2) a private wave travelling along this line only: own length, own speed, sometimes reversed
      pLen: between(r, 620, 1000),  pSpeed: between(r, 8, 20) * (r() < 0.3 ? -1 : 1),  pPh: between(r, 0, 6.283),
      // (3) a second, quieter private wave with its own rhythm
      qLen: between(r, 400, 620),  qSpeed: between(r, 5, 12) * (r() < 0.5 ? -1 : 1),  qPh: between(r, 0, 6.283),
      // (4) this line's strength slowly swells and eases on its own clock
      bW: between(r, 0.04, 0.10),  bP: between(r, 0, 6.283),
      // (5) small per-line timing difference on the shared swell
      sSpeed: between(r, 0.9, 1.1)
